insert into public.services (slug, name, summary, description, who_its_for, what_to_expect, duration_minutes, price_from, price_to, price_note, sort_order) values
('general-consultation','General consultation','A thorough check-up and a clear plan.','An unhurried examination of your teeth, gums and bite, with a conversation about your goals and any concerns.','Anyone new to the clinic, or overdue for a check-up.','We review your history, examine your mouth, and take images if needed. You leave with a written plan and no pressure.',30,2000,2000,'Placeholder price',10),
('dental-cleaning','Dental cleaning','Professional scaling and polishing.','Gentle removal of plaque and tartar that brushing cannot reach, followed by polishing.','Most adults, typically every six months, or as your dentist advises.','Your hygienist scales around each tooth and gum line, then polishes. Some sensitivity afterwards is normal.',45,3500,5000,'Final price depends on the examination',20),
('teeth-whitening','Teeth whitening','Supervised whitening for a brighter shade.','A dentist-supervised whitening treatment. Results vary between patients and are not guaranteed.','Adults with healthy teeth and gums who want a lighter shade.','We check suitability, protect your gums, apply the whitening agent and review your shade.',60,15000,25000,'Placeholder price',30),
('dental-fillings','Dental fillings','Tooth-coloured restorations.','Removal of decayed tissue and restoration with a tooth-coloured material.','Patients whose dentist has found a cavity or a worn filling.','Numbing if needed, careful cleaning of the area, placing and shaping the filling, then a bite check.',45,4000,8000,'Depends on size and location',40),
('root-canal','Root canal treatment','Saving a tooth with an infected nerve.','Treatment to clean the inside of a tooth and seal it, so the tooth can often be kept.','Patients advised by a dentist that the tooth nerve is affected.','An examination and X-ray come first. Treatment may need more than one visit.',90,null,null,'The clinic must confirm this price after an examination',50),
('dental-implants','Dental implants','Replacement for a missing tooth.','A titanium post placed in the jaw to support a crown, assessed individually.','Adults with a missing tooth and sufficient healthy bone.','Planning begins with a consultation and imaging. Treatment happens in stages over several months.',60,null,null,'The clinic must confirm this price after a consultation',60),
('braces-orthodontics','Braces and orthodontics','Straightening teeth and correcting the bite.','Fixed braces to align teeth, with regular adjustments.','Teenagers and adults with crowding, gaps or bite concerns.','An assessment and records, a treatment plan, then adjustment visits roughly every month.',45,null,null,'The clinic must confirm this price after an assessment',70),
('clear-aligners','Clear aligners','Removable, near-invisible aligners.','A series of clear trays that gradually move teeth, suitable for selected cases.','Adults with mild to moderate alignment concerns.','A scan, a digital plan, then new trays every few weeks with regular check-ins.',45,null,null,'The clinic must confirm this price after an assessment',80),
('veneers','Veneers','Thin shells to reshape the front of a tooth.','Custom-made porcelain or composite shells bonded to the front of a tooth.','Patients wanting to change the shape, size or colour of front teeth.','A design consultation, preparing the tooth, a temporary, then fitting the final veneer.',60,null,null,'The clinic must confirm this price after a consultation',90),
('tooth-extraction','Tooth extraction','Removal of a tooth when it cannot be saved.','Careful removal of a damaged or problem tooth, with aftercare advice.','Patients whose dentist advises that a tooth cannot be restored.','Numbing, gentle removal, and clear written aftercare instructions.',45,3000,10000,'Surgical extractions cost more',100),
('gum-treatment','Gum treatment','Care for sore or bleeding gums.','Deep cleaning and a plan to bring gum health back under control.','Patients with bleeding, swollen or receding gums.','An assessment of your gums, a deep clean, and a home-care plan.',60,6000,12000,'Placeholder price',110),
('pediatric-dentistry','Pediatric dentistry','Friendly, gentle care for children.','Check-ups, cleanings and preventive care adapted for children.','Children and their parents or carers.','A calm introduction, a gentle check-up, and tips for brushing at home.',30,2000,3500,'Placeholder price',120)
insert into public.faqs (question, answer, category, sort_order) values
('What should I expect at my first visit?','We start with a conversation about your history and concerns, then a gentle examination. Please arrive 10 minutes early and bring any previous dental records.','first-visit',10),
('Is a dental cleaning painful?','Most people feel pressure rather than pain. Tell us if anything is uncomfortable and we will pause or adjust.','cleaning',20),
('How often should I visit?','Many adults visit every six months, but your dentist will advise a schedule that suits you.','general',30),
('How do I cancel or reschedule?','Use the link in your confirmation email, or call the clinic. Please give at least 24 hours notice where possible.','booking',40),
('What if I have severe pain or swelling?','Call the clinic straight away. For facial swelling, trouble breathing or uncontrolled bleeding, go to the nearest emergency department.','urgent',50);
